def bgrid(p, D):
    return ["".join("|" if q > "." and int(q) >= D - i else "." for q in p) for i in range(D)]

def far(starts, a):
    return all(abs(a - b) >= 4 for b in starts)

def cells_of(p, D):
    bg = bgrid(p, D)
    return [(i, c) for i in range(D) for c in range(len(p)) if bg[i][c] == "|"]

def sides(bg, W, i, c):
    out = []
    if c >= 3 and bg[i][c-3:c] == "...":
        out.append((c - 3, 0))
    if c + 4 <= W and bg[i][c+1:c+4] == "...":
        out.append((c + 1, 1))
    return out

def all_cands(p, D):
    W = len(p); bg = bgrid(p, D); out = []
    for i in range(D):
        b = bg[i]; row = []
        for a in range(W - 2):
            if b[a:a+3] == "...":
                for d in (0, 1):
                    if d == 0:
                        nb = a + 3 < W and b[a+3] == "|"
                        tl = a > 0 and b[a-1] == "|"
                    else:
                        nb = a > 0 and b[a-1] == "|"
                        tl = a + 3 < W and b[a+3] == "|"
                    row.append((a, d, nb, tl))
        out.append(row)
    return out

def render(p, D, rows):
    bg = bgrid(p, D); W = len(p)
    out = ["~" * W]
    for i in range(D):
        row = list(bg[i])
        for (a, d) in rows[i]:
            row[a:a+3] = list("><>" if d == 0 else "<><")
        out.append("".join(row))
    out.append("#" * W)
    return "\n".join(out)

def stats(p, D, rows):
    W = len(p); bg = bgrid(p, D)
    F = R = Lf = fnib = tail = 0
    ps = pnn = ptt = 0
    spots = set(); touched = set(); perrow = []
    for i in range(D):
        rs = sorted(rows[i]); perrow.append(len(rs))
        for (a, d) in rs:
            F += 1
            if d == 0: R += 1
            else: Lf += 1
            nose = a + 3 if d == 0 else a - 1
            back = a - 1 if d == 0 else a + 3
            if 0 <= nose < W and bg[i][nose] == "|":
                fnib += 1; spots.add((i, nose)); touched.add(nose)
            if 0 <= back < W and bg[i][back] == "|":
                tail += 1; touched.add(back)
        for u, v in zip(rs, rs[1:]):
            if u[1] == v[1]: ps += 1
            elif u[1] == 0: pnn += 1
            else: ptt += 1
    pl = sum(1 for q in p if q > ".")
    pc = sum(int(q) for q in p if q > ".")
    nib = len(spots)
    return dict(ncol=len({c for (_, c) in spots}), dbl=fnib - nib,F=F, R=R, Lf=Lf, nib=nib, fnib=fnib, tail=tail, touch=fnib + tail,
                pl=pl, pc=pc, D=D, bot=perrow[-1], top=perrow[0], mx=max(perrow),
                ps=ps, pnn=pnn, ptt=ptt, pt=len(touched), perrow=perrow)

DEC = ("F","R","Lf","fnib","tail","touch","pl","pc","D","bot","top","mx","ps","pnn","ptt","pt")

def decoys_ok(p, D, rows, N):
    s = stats(p, D, rows)
    if s["nib"] != N: return False
    if s["fnib"] <= N: return False
    if s["tail"] < 2: return False
    if s["R"] < 2 or s["Lf"] < 2: return False
    if s["F"] - s["touch"] < 2: return False
    bad = {s[k] for k in DEC}
    bad |= {s["F"] - s["D"], s["F"] - s["nib"], s["fnib"] - s["nib"], s["touch"] - s["nib"]}
    return N not in bad

def solve(clue):
    p, n = clue.split("/")
    N = int(n); W = len(p)
    r = random.Random(clue)
    pre = {}
    for D in (4, 5, 6):
        bg = bgrid(p, D)
        cs = [(i, c) for (i, c) in cells_of(p, D) if sides(bg, W, i, c)]
        pre[D] = (bg, cs, all_cands(p, D))
    Ds = [D for D in (4, 5, 6) if len(pre[D][1]) >= N and D != N]
    if not Ds: return ""
    for _ in range(4000):
        D = r.choice(Ds)
        bg, cs, cand = pre[D]
        pick = r.sample(cs, N)
        dbl = [c for c in pick if len(sides(bg, W, *c)) == 2]
        if not dbl: continue
        k = min(r.choice((1, 1, 2, 2, 3)), len(dbl), N)
        want_dbl = set(r.sample(dbl, k))
        rows = [[] for _ in range(D)]
        ok = True
        for (i, c) in pick:
            sd = sides(bg, W, i, c)
            use = sd if (i, c) in want_dbl else [r.choice(sd)]
            for (a, d) in use:
                if far([x[0] for x in rows[i]], a):
                    rows[i].append((a, d))
                else:
                    ok = False
            if not ok: break
        if not ok: continue
        for i in range(D):
            fill = [x for x in cand[i] if not x[2]]
            r.shuffle(fill)
            if r.random() < 0.75: fill.sort(key=lambda z: not z[3])
            want = r.randint(1, 2) + (1 if not rows[i] else 0)
            for (a, d, nb, tl) in fill:
                if want == 0: break
                if far([x[0] for x in rows[i]], a):
                    rows[i].append((a, d)); want -= 1
            if not rows[i]: ok = False; break
        if ok and decoys_ok(p, D, rows, N):
            return render(p, D, rows)
    return ""

